// Scan: every raw piece of evidence the system holds, at the current checkpoint, as one 3D space.
import { Suspense, useEffect, useMemo, useState } from "react";
import { Canvas } from "@react-three/fiber";
import { useQuery } from "@tanstack/react-query";
import { X } from "lucide-react";
import { api } from "@/lib/api";
import type { Comment, PointsPayload, SourcesPayload } from "@/lib/types";
import { useCheckpoint } from "@/state/checkpoint";
import { Scene } from "./Scene";
import { CAR_NAME, MARKET_NAME } from "./layout";
import "./scan.css";

const fmt = (n: number | undefined | null) => (n == null ? "–" : n.toLocaleString("en-US"));

type Dim = "car" | "market" | "channel" | "type" | "engine";
const DIMS: { id: Dim; name: string }[] = [
  { id: "car", name: "Car" }, { id: "market", name: "Market" }, { id: "channel", name: "Channel" },
  { id: "type", name: "Label" }, { id: "engine", name: "Engine" },
];
function valueName(dim: Dim, v: string | null): string {
  if (v == null) return "Unlabelled";
  if (dim === "car") return CAR_NAME[v] ?? v;
  if (dim === "market") return MARKET_NAME[v] ?? v;
  return v;
}

export function Scan() {
  const { from, sweepId, position, current, checkpoints } = useCheckpoint();
  const points = useQuery({ queryKey: ["scan", "points"], queryFn: () => api.get<PointsPayload>("/api/scan/points"), staleTime: Infinity });
  const sources = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity });
  const [dim, setDim] = useState<Dim>("car");
  const [isolate, setIsolate] = useState<Set<number>>(new Set());
  const [hover, setHover] = useState<{ i: number; x: number; y: number } | null>(null);
  const [picked, setPicked] = useState<number | null>(null);
  const fromPosition = (checkpoints?.find((c) => c.id === from)?.position ?? position);

  const mask = useMemo(() => {
    const n = points.data?.n ?? 0;
    const m = new Uint8Array(n).fill(1);
    if (!points.data || isolate.size === 0) return m;
    const col = points.data.cols[dim];
    for (let i = 0; i < n; i++) m[i] = isolate.has(col[i]) ? 1 : 0;
    return m;
  }, [points.data, dim, isolate]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") { setPicked(null); setIsolate(new Set()); } };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const pickedId = picked != null ? points.data?.cols.id[picked] : null;
  const hoverId = hover ? points.data?.cols.id[hover.i] : null;

  return (
    <main className="scan" aria-label="Raw evidence at the selected checkpoint">
      <div className="scan-canvas" style={{ cursor: hover ? "pointer" : "grab" }}>
        {points.data && (
          <Canvas dpr={[1, 2]} camera={{ position: [0, 2.3, 5.3], fov: 40, near: 0.05, far: 50 }}
                  raycaster={{ params: { Points: { threshold: 0.018 }, Line: { threshold: 0 }, Mesh: {}, LOD: {}, Sprite: {} } }}
                  gl={{ antialias: true, alpha: false }} onCreated={({ gl }) => gl.setClearColor("#000000")}>
            <Suspense fallback={null}>
              <Scene points={points.data} sources={sources.data} mask={mask} position={position} fromPosition={fromPosition}
                     sweepId={sweepId} hover={hover?.i ?? null}
                     onHover={(i, x, y) => setHover(i == null ? null : { i, x, y })} onPick={setPicked} />
            </Suspense>
          </Canvas>
        )}
        {points.isPending && <div className="scan-state"><span className="scan-pulse" aria-hidden />Scanning</div>}
        {points.isError && <div className="scan-state error">{(points.error as Error).message}</div>}
      </div>

      <Readout />

      {points.data && (
        <Key points={points.data} position={position} dim={dim} isolate={isolate}
             onDim={(d) => { setDim(d); setIsolate(new Set()); }}
             onToggle={(v) => setIsolate((s) => { const n = new Set(s); n.has(v) ? n.delete(v) : n.add(v); return n; })}
             onClear={() => setIsolate(new Set())} />
      )}

      {hover && hoverId != null && picked == null && <HoverCard id={hoverId} x={hover.x} y={hover.y} acquiredHere={points.data!.cols.cp[hover.i] === position} />}
      {pickedId != null && <CommentSheet id={pickedId} onClose={() => setPicked(null)} cpLabel={(id) => checkpoints?.find((c) => c.id === id)?.label ?? id} />}

      <span className="sr-only" aria-live="polite">{current ? `${current.label}: ${fmt(current.sources.feedback.visible)} comments` : ""}</span>
    </main>
  );
}

/* ------------------------------------------------------------------------------------------- readout */
function Glyph({ kind }: { kind: "comment" | "study" | "option" | "sales" | "research" }) {
  const c = "currentColor";
  return (
    <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden className="glyph">
      {kind === "comment" && <><circle cx="4" cy="6" r="1.6" fill={c} /><circle cx="9" cy="4" r="1.1" fill={c} /><circle cx="8.5" cy="9.5" r="1.4" fill={c} /></>}
      {kind === "study" && <><path d="M2 7h10" stroke={c} strokeOpacity=".35" /><path d="M4 7V3M7 7v5M10 7V4" stroke={c} strokeWidth="1.3" /></>}
      {kind === "option" && <>{[2.5, 5.5, 8.5, 11.5].map((x) => <circle key={x} cx={x} cy="7" r="1" fill={c} />)}</>}
      {kind === "sales" && <><rect x="2.5" y="6" width="2" height="6" fill={c} /><rect x="6" y="3" width="2" height="9" fill={c} /><rect x="9.5" y="2" width="2" height="10" fill="none" stroke={c} /></>}
      {kind === "research" && <><path d="M1.5 9.5a6 6 0 0 1 11 0" fill="none" stroke={c} strokeDasharray="1.5 1.5" /><circle cx="7" cy="4.2" r="1.4" fill={c} /></>}
    </svg>
  );
}

function Readout() {
  const { current, position } = useCheckpoint();
  const s = current?.sources;
  const plus = (n: number | undefined) => (position > 1 && n ? <span className="plus">+{fmt(n)}</span> : null);
  return (
    <header className="readout">
      <div className="wordmark">Successor</div>
      <div className="readout-main">
        <span className="num readout-xl">{fmt(s?.feedback.visible)}</span>
        <span className="readout-sub"><Glyph kind="comment" /><span className="label">customer comments</span>{plus(s?.feedback.new)}</span>
      </div>
      <dl className="readout-row">
        <div><dt><Glyph kind="research" /><span className="label">research</span></dt><dd className="num">{fmt(s?.research.visible)}{plus(s?.research.new)}</dd></div>
        <div><dt><Glyph kind="study" /><span className="label">study items</span></dt><dd className="num">{fmt(s?.study.visible)}</dd></div>
        <div><dt><Glyph kind="option" /><span className="label">options</span></dt><dd className="num">{fmt(s?.option_list.visible)}</dd></div>
        <div><dt><Glyph kind="sales" /><span className="label">sales rows</span></dt><dd className="num">{fmt(s?.sales.visible)}</dd></div>
      </dl>
    </header>
  );
}

/* ------------------------------------------------------------------------------------------- key */
function Key(p: { points: PointsPayload; position: number; dim: Dim; isolate: Set<number>; onDim: (d: Dim) => void; onToggle: (v: number) => void; onClear: () => void }) {
  const values = p.points.dict[p.dim] as (string | null)[];
  const counts = useMemo(() => {
    const col = p.points.cols[p.dim], cps = p.points.cols.cp;
    const vis = new Array(values.length).fill(0), nu = new Array(values.length).fill(0);
    for (let i = 0; i < col.length; i++) {
      if (col[i] < 0 || cps[i] > p.position) continue;
      vis[col[i]]++;
      if (p.position > 1 && cps[i] === p.position) nu[col[i]]++;
    }
    return { vis, nu };
  }, [p.points, p.dim, p.position, values.length]);
  const max = Math.max(1, ...counts.vis);
  return (
    <nav className="key" aria-label="Filter comments">
      <div className="key-dims" role="tablist">
        {DIMS.map((d) => <button key={d.id} role="tab" aria-selected={p.dim === d.id} onClick={() => p.onDim(d.id)}>{d.name}</button>)}
      </div>
      <ul className="key-values">
        {values.map((v, i) => {
          const n = counts.vis[i];
          if (!n && !counts.nu[i]) return null;
          const on = p.isolate.size === 0 || p.isolate.has(i);
          return (
            <li key={i}>
              <button aria-pressed={p.isolate.has(i)} data-dim={on ? undefined : ""} onClick={() => p.onToggle(i)}>
                <span className="key-name">{valueName(p.dim, v)}</span>
                <span className="key-bar" aria-hidden><span style={{ transform: `scaleX(${n / max})` }} /></span>
                <span className="key-n">{fmt(n)}</span>
              </button>
            </li>
          );
        })}
      </ul>
      {p.isolate.size > 0 && <button className="key-clear" onClick={p.onClear}>Show all <span className="label">Esc</span></button>}
    </nav>
  );
}

/* ------------------------------------------------------------------------------------------- comment */
const useComment = (id: number) => useQuery({ queryKey: ["comment", id], queryFn: () => api.get<Comment>(`/api/scan/comment/${id}`), staleTime: Infinity });

function HoverCard({ id, x, y, acquiredHere }: { id: number; x: number; y: number; acquiredHere: boolean }) {
  const q = useComment(id);
  const left = Math.min(x + 16, window.innerWidth - 336), top = Math.min(y + 16, window.innerHeight - 140);
  return (
    <div className="hovercard" style={{ left, top }} role="tooltip">
      <p>{q.data ? q.data.text : " "}</p>
      {q.data && (
        <div className="hovercard-meta">
          <i className={`mark ${acquiredHere ? "new" : "held"}`} aria-hidden />
          <span>{CAR_NAME[q.data.car] ?? q.data.car}</span><span>{q.data.country}</span><span>{q.data.channel}</span>
        </div>
      )}
    </div>
  );
}

function CommentSheet({ id, onClose, cpLabel }: { id: number; onClose: () => void; cpLabel: (id: string) => string }) {
  const q = useComment(id);
  const c = q.data;
  const label = c?.bmw_labels?.[0];
  return (
    <aside className="sheet" aria-label="Customer comment">
      <button className="sheet-close" onClick={onClose} aria-label="Close"><X size={16} /></button>
      {!c && <div className="sheet-skel" aria-hidden><span /><span /><span /></div>}
      {c && (
        <>
          <blockquote className="sheet-quote">{c.text}</blockquote>
          <dl className="sheet-facts">
            <div><dt className="label">Car</dt><dd>{CAR_NAME[c.car] ?? c.car}</dd></div>
            <div><dt className="label">Market</dt><dd>{MARKET_NAME[c.market] ?? c.market}{c.country && c.country !== c.market ? ` · ${c.country}` : ""}</dd></div>
            <div><dt className="label">Channel</dt><dd>{c.channel ?? "–"}</dd></div>
            <div><dt className="label">Engine</dt><dd>{c.engine ?? "–"}</dd></div>
            <div><dt className="label">BMW label</dt><dd>{label?.feedback_type ?? "Unlabelled"}{label?.vfc_level2 && label.vfc_level2 !== "no_class_found" ? ` · ${label.vfc_level2}` : ""}</dd></div>
            <div><dt className="label">Acquired</dt><dd><i className="mark new" aria-hidden /> {cpLabel(c.checkpoint)}</dd></div>
          </dl>
          <div className="sheet-ref label">{c.external_id}</div>
        </>
      )}
    </aside>
  );
}

