1	// The scan volume (react-three-fiber). One shader decides, per contact, whether the current sweep has acquired it:
2	// contacts known at the earlier checkpoint are held (white); contacts the current sweep acquires turn blue and flare
3	// as the sweep plane passes their bearing. The same rule drives the comments and the dated research on the time ring.
4	import { useEffect, useMemo, useRef } from "react";
5	import { useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
6	import { Html, OrbitControls } from "@react-three/drei";
7	import * as THREE from "three";
8	import type { PointsPayload, SourcesPayload } from "@/lib/types";
9	import { CARS, CAR_NAME, R, SWEEP_START, TAU, TIME_START, polar, sector, timeAngle } from "./layout";
10	
11	const VERT = /* glsl */ `
12	attribute float aCp; attribute float aSel; attribute float aAz; attribute float aSize; attribute float aIdx;
13	uniform float uCp, uFrom, uSweep, uStart, uScale, uHover, uDim;
14	varying vec3 vColor; varying float vAlpha;
15	const float TAU = 6.2831853;
16	void main() {
17	  float lo = min(uCp, uFrom), hi = max(uCp, uFrom);
18	  float d = mod(aAz - uStart + 2.0 * TAU, TAU) / TAU;
19	  float passed = step(d, uSweep);
20	  float vis = aCp <= lo ? 1.0 : (aCp <= hi ? (uCp > uFrom ? passed : 1.0 - passed) : 0.0);
21	  float flare = (uCp > uFrom && aCp > lo && aCp <= hi) ? passed * exp(-max(uSweep - d, 0.0) * 18.0) : 0.0;
22	  bool acquired = abs(aCp - uCp) < 0.5;
23	  vColor = mix(acquired ? vec3(0.32, 0.6, 1.0) : vec3(0.92, 0.94, 0.97), vec3(1.0), flare);
24	  float hov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
25	  vAlpha = vis * mix(uDim, 1.0, aSel) * (acquired ? 0.92 : 0.62) + hov;
26	  vec4 mv = modelViewMatrix * vec4(position, 1.0);
27	  gl_Position = projectionMatrix * mv;
28	  gl_PointSize = aSize * uScale * (1.0 + flare * 2.2 + hov * 2.5) / -mv.z;
29	}`;
30	const FRAG = /* glsl */ `
31	varying vec3 vColor; varying float vAlpha;
32	void main() {
33	  float r = length(gl_PointCoord - 0.5);
34	  if (r > 0.5) discard;
35	  gl_FragColor = vec4(vColor, min(vAlpha, 1.0) * smoothstep(0.5, 0.28, r));
36	}`;
37	
38	function contactMaterial(scale: number) {
39	  return new THREE.ShaderMaterial({
40	    vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false,
41	    uniforms: {
42	      uCp: { value: 2 }, uFrom: { value: 2 }, uSweep: { value: 1 }, uStart: { value: SWEEP_START },
43	      uScale: { value: scale }, uHover: { value: -1 }, uDim: { value: 0.06 },
44	    },
45	  });
46	}
47	
48	/* ------------------------------------------------------------------------------------------- sweep clock */
49	function useSweep(mats: THREE.ShaderMaterial[], position: number, fromPosition: number, sweepId: number, onAngle: (a: number | null) => void) {
50	  const start = useRef<number | null>(null);
51	  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
52	  useEffect(() => {
53	    for (const m of mats) { m.uniforms.uCp.value = position; m.uniforms.uFrom.value = fromPosition; m.uniforms.uSweep.value = reduced ? 1 : 0; }
54	    start.current = reduced || position === fromPosition ? null : performance.now();
55	  }, [sweepId]); // eslint-disable-line react-hooks/exhaustive-deps
56	  useFrame(() => {
57	    if (start.current == null) { onAngle(null); return; }
58	    const t = Math.min(1, (performance.now() - start.current) / 2200);
59	    const e = 1 - Math.pow(1 - t, 3);
60	    for (const m of mats) m.uniforms.uSweep.value = e;
61	    onAngle(t < 1 ? SWEEP_START + e * TAU : null);
62	    if (t >= 1) { start.current = null; for (const m of mats) m.uniforms.uFrom.value = m.uniforms.uCp.value; }
63	  });
64	}
65	
66	/* ------------------------------------------------------------------------------------------- comments */
67	interface SceneProps {
68	  points: PointsPayload;
69	  sources: SourcesPayload | undefined;
70	  mask: Uint8Array;            // 1 = matches the current key filter
71	  position: number; fromPosition: number; sweepId: number;
72	  hover: number | null;
73	  onHover: (i: number | null, x: number, y: number) => void;
74	  onPick: (i: number) => void;
75	}
76	
77	export function Scene(p: SceneProps) {
78	  const { gl } = useThree();
79	  const dpr = gl.getPixelRatio();
80	  const commentMat = useMemo(() => contactMaterial(15 * dpr), [dpr]);
81	  const researchMat = useMemo(() => contactMaterial(20 * dpr), [dpr]);
82	  const sweepRef = useRef<THREE.Group>(null);
83	
84	  const geom = useMemo(() => {
85	    const c = p.points.cols, n = p.points.n;
86	    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
87	    for (let i = 0; i < n; i++) {
88	      pos[i * 3] = c.x[i]; pos[i * 3 + 1] = c.y[i] * 0.72; pos[i * 3 + 2] = c.z[i];
89	      cp[i] = c.cp[i]; az[i] = Math.atan2(c.z[i], c.x[i]); idx[i] = i;
90	      size[i] = 0.85 + Math.min(0.8, Math.sqrt(c.len[i] / 300));
91	    }
92	    const g = new THREE.BufferGeometry();
93	    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
94	    g.setAttribute("aCp", new THREE.BufferAttribute(cp, 1));
95	    g.setAttribute("aAz", new THREE.BufferAttribute(az, 1));
96	    g.setAttribute("aSize", new THREE.BufferAttribute(size, 1));
97	    g.setAttribute("aIdx", new THREE.BufferAttribute(idx, 1));
98	    g.setAttribute("aSel", new THREE.BufferAttribute(new Float32Array(n).fill(1), 1));
99	    g.computeBoundingSphere();
100	    return g;
101	  }, [p.points]);
102	
103	  useEffect(() => {
104	    const a = geom.getAttribute("aSel") as THREE.BufferAttribute;
105	    for (let i = 0; i < p.mask.length; i++) a.setX(i, p.mask[i]);
106	    a.needsUpdate = true;
107	  }, [geom, p.mask]);
108	  useEffect(() => { commentMat.uniforms.uHover.value = p.hover ?? -1; }, [commentMat, p.hover]);
109	
110	  const research = useMemo(() => {
111	    const items = p.sources?.research ?? [];
112	    const n = items.length;
113	    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
114	    items.forEach((it, i) => {
115	      const a = timeAngle(it.published_at);
116	      const lane = (it.id % 7) / 7;                         // spread same-day items across the ring's width
117	      const [x, , z] = polar(R.time + (lane - 0.5) * 0.12, a);
118	      pos.set([x, (lane - 0.5) * 0.05, z], i * 3);
119	      cp[i] = it.new ? 2 : 1; az[i] = a; size[i] = it.tier === "T1" ? 1.5 : 1.1; idx[i] = -10;
120	    });
121	    const g = new THREE.BufferGeometry();
122	    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
123	    g.setAttribute("aCp", new THREE.BufferAttribute(cp, 1));
124	    g.setAttribute("aAz", new THREE.BufferAttribute(az, 1));
125	    g.setAttribute("aSize", new THREE.BufferAttribute(size, 1));
126	    g.setAttribute("aIdx", new THREE.BufferAttribute(idx, 1));
127	    g.setAttribute("aSel", new THREE.BufferAttribute(new Float32Array(n).fill(1), 1));
128	    return g;
129	  }, [p.sources]);
130	
131	  useSweep([commentMat, researchMat], p.position, p.fromPosition, p.sweepId, (a) => {
132	    const g = sweepRef.current;
133	    if (!g) return;
134	    g.visible = a != null;
135	    if (a != null) g.rotation.y = -a;
136	  });
137	
138	  const visibleAt = (i: number) => p.mask[i] === 1 && p.points.cols.cp[i] <= p.position;
139	  const move = (e: ThreeEvent<PointerEvent>) => {
140	    const hit = e.intersections.find((h) => h.object === e.object && h.index != null && visibleAt(h.index));
141	    if (hit?.index != null) { e.stopPropagation(); p.onHover(hit.index, e.nativeEvent.clientX, e.nativeEvent.clientY); }
142	    else p.onHover(null, 0, 0);
143	  };
144	  const click = (e: ThreeEvent<MouseEvent>) => {
145	    const hit = e.intersections.find((h) => h.object === e.object && h.index != null && visibleAt(h.index));
146	    if (hit?.index != null) { e.stopPropagation(); p.onPick(hit.index); }
147	  };
148	
149	  return (
150	    <>
151	      <OrbitControls makeDefault enablePan={false} minDistance={2.2} maxDistance={9} autoRotate autoRotateSpeed={0.25}
152	                     enableDamping dampingFactor={0.08} maxPolarAngle={Math.PI * 0.62} />
153	      <points geometry={geom} material={commentMat} onPointerMove={move} onPointerOut={() => p.onHover(null, 0, 0)} onClick={click} />
154	      <points geometry={research} material={researchMat} />
155	      <Rings sources={p.sources} />
156	      <group ref={sweepRef} visible={false}><SweepBlade /></group>
157	    </>
158	  );
159	}
160	
161	/* ------------------------------------------------------------------------------------------- the sweep */
162	function SweepBlade() {
163	  const mat = useMemo(() => new THREE.ShaderMaterial({
164	    transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending,
165	    vertexShader: "varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }",
166	    fragmentShader: "varying vec2 vUv; void main(){ float a = (1.0 - vUv.x * 0.7) * (1.0 - abs(vUv.y - 0.5) * 2.0); gl_FragColor = vec4(0.18, 0.45, 0.95, 0.32 * a); }",
167	  }), []);
168	  return (
169	    <>
170	      <mesh material={mat} position={[R.time / 2 + 0.1, 0, 0]}><planeGeometry args={[R.time + 0.2, 1.4]} /></mesh>
171	      <mesh position={[(R.time + 0.2) / 2, 0, 0]}><boxGeometry args={[R.time + 0.2, 0.004, 0.004]} /><meshBasicMaterial color="#4d94ff" /></mesh>
172	    </>
173	  );
174	}
175	
176	/* ------------------------------------------------------------------------------------------- source rings */
177	function ringPoints(r: number, a0 = 0, a1 = TAU, seg = 256) {
178	  const pts: THREE.Vector3[] = [];
179	  for (let i = 0; i <= seg; i++) { const a = a0 + ((a1 - a0) * i) / seg; pts.push(new THREE.Vector3(...polar(r, a))); }
180	  return new THREE.BufferGeometry().setFromPoints(pts);
181	}
182	
183	function Rings({ sources }: { sources: SourcesPayload | undefined }) {
184	  const lines = useMemo(() => {
185	    const guide = new THREE.LineBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.1 });
186	    const out: THREE.Line[] = [R.study, R.options, R.sales].flatMap((r) => CARS.map((car) => new THREE.Line(ringPoints(r, ...sector(car), 64), guide)));
187	    const time = new THREE.Line(ringPoints(R.time, TIME_START - 0.12, TIME_START + (300 / 360) * TAU, 360),
188	      new THREE.LineDashedMaterial({ color: "#ffffff", transparent: true, opacity: 0.22, dashSize: 0.02, gapSize: 0.025 }));
189	    time.computeLineDistances();
190	    out.push(time);
191	    return out;
192	  }, []);
193	
194	  // study: one radial tick per item, outward = above its own column's average, inward = below (z-score)
195	  const study = useMemo(() => {
196	    const list = sources?.study ?? [];
197	    const v: number[] = [];
198	    const groups = new Map<string, typeof list>();
199	    for (const s of list) { const k = s.car; groups.set(k, [...(groups.get(k) ?? []), s]); }
200	    for (const [car, items] of groups) {
201	      const [a0, a1] = sector(car);
202	      items.forEach((s, i) => {
203	        const a = a0 + ((a1 - a0) * (i + 0.5)) / items.length;
204	        const z = Math.max(-2.5, Math.min(2.5, s.z ?? 0)) * 0.05;
205	        v.push(...polar(R.study, a), ...polar(R.study + z, a));
206	      });
207	    }
208	    return new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3));
209	  }, [sources]);
210	
211	  // options: one dot per equipment option of today's car
212	  const options = useMemo(() => {
213	    const v: number[] = [];
214	    for (const o of sources?.options ?? []) {
215	      const [a0, a1] = sector(o.car);
216	      for (let i = 0; i < o.n; i++) v.push(...polar(R.options + ((i % 3) - 1) * 0.018, a0 + ((a1 - a0) * (i + 0.5)) / o.n));
217	    }
218	    return new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3));
219	  }, [sources]);
220	
221	  // sales: one bar per car × market × year; 2030 forecast drawn as an outline
222	  const bars = useMemo(() => {
223	    const rows = (sources?.sales ?? []).filter((s) => s.units && s.units > 0);
224	    const byCar = new Map<string, typeof rows>();
225	    for (const s of rows) byCar.set(s.car, [...(byCar.get(s.car) ?? []), s]);
226	    const out: { pos: [number, number, number]; rot: number; h: number; forecast: boolean }[] = [];
227	    for (const [car, items] of byCar) {
228	      const [a0, a1] = sector(car);
229	      items.forEach((s, i) => {
230	        const a = a0 + ((a1 - a0) * (i + 0.5)) / items.length;
231	        const h = Math.max(0.01, (s.units! / 120000) * 0.3);
232	        out.push({ pos: polar(R.sales, a, h / 2), rot: -a, h, forecast: !!s.is_forecast });
233	      });
234	    }
235	    return out;
236	  }, [sources]);
237	
238	  return (
239	    <group>
240	      {lines.map((l, i) => <primitive key={i} object={l} />)}
241	      <lineSegments geometry={study}><lineBasicMaterial color="#dfe4ea" transparent opacity={0.55} /></lineSegments>
242	      <points geometry={options}><pointsMaterial color="#dfe4ea" size={0.012} transparent opacity={0.55} /></points>
243	      {bars.map((b, i) => (
244	        <mesh key={i} position={b.pos} rotation={[0, b.rot, 0]}>
245	          <boxGeometry args={[0.008, b.h, 0.008]} />
246	          {b.forecast ? <meshBasicMaterial color="#4d94ff" wireframe transparent opacity={0.4} /> : <meshBasicMaterial color="#dfe4ea" transparent opacity={0.45} />}
247	        </mesh>
248	      ))}
249	      {CARS.map((car) => {
250	        const [a0, a1] = sector(car);
251	        return (
252	          <Html key={car} position={polar(R.labels, (a0 + a1) / 2)} center zIndexRange={[10, 0]}>
253	            <div className="ring-label"><b>{CAR_NAME[car]}</b><span>{car}</span></div>
254	          </Html>
255	        );
256	      })}
257	      {[["JUL 25", "2025-07-01"], ["JAN 26", "2026-01-31"], ["JUL 26", "2026-07-31"]].map(([t, d]) => (
258	        <Html key={t} position={polar(R.time + 0.16, timeAngle(d), 0)} center zIndexRange={[10, 0]}>
259	          <div className="time-label">{t}</div>
260	        </Html>
261	      ))}
262	    </group>
263	  );
264	}
