// The scan volume (react-three-fiber). One shader decides, per contact, whether the current sweep has acquired it:
// contacts known at the earlier checkpoint are held (white); contacts the current sweep acquires turn blue and flare
// as the sweep plane passes their bearing. The same rule drives the comments and the dated research on the time ring.
import { useEffect, useMemo, useRef } from "react";
import { useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
import { Html, OrbitControls } from "@react-three/drei";
import * as THREE from "three";
import type { PointsPayload, SourcesPayload } from "@/lib/types";
import { CARS, CAR_NAME, R, SWEEP_START, TAU, TIME_START, polar, sector, timeAngle } from "./layout";

const VERT = /* glsl */ `
attribute float aCp; attribute float aSel; attribute float aAz; attribute float aSize; attribute float aIdx;
uniform float uCp, uFrom, uSweep, uStart, uScale, uHover, uDim;
varying vec3 vColor; varying float vAlpha;
const float TAU = 6.2831853;
void main() {
  float lo = min(uCp, uFrom), hi = max(uCp, uFrom);
  float d = mod(aAz - uStart + 2.0 * TAU, TAU) / TAU;
  float passed = step(d, uSweep);
  float vis = aCp <= lo ? 1.0 : (aCp <= hi ? (uCp > uFrom ? passed : 1.0 - passed) : 0.0);
  float flare = (uCp > uFrom && aCp > lo && aCp <= hi) ? passed * exp(-max(uSweep - d, 0.0) * 18.0) : 0.0;
  bool acquired = abs(aCp - uCp) < 0.5;
  vColor = mix(acquired ? vec3(0.32, 0.6, 1.0) : vec3(0.92, 0.94, 0.97), vec3(1.0), flare);
  float hov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
  vAlpha = vis * mix(uDim, 1.0, aSel) * (acquired ? 0.92 : 0.62) + hov;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * mv;
  gl_PointSize = aSize * uScale * (1.0 + flare * 2.2 + hov * 2.5) / -mv.z;
}`;
const FRAG = /* glsl */ `
varying vec3 vColor; varying float vAlpha;
void main() {
  float r = length(gl_PointCoord - 0.5);
  if (r > 0.5) discard;
  gl_FragColor = vec4(vColor, min(vAlpha, 1.0) * smoothstep(0.5, 0.28, r));
}`;

function contactMaterial(scale: number) {
  return new THREE.ShaderMaterial({
    vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false,
    uniforms: {
      uCp: { value: 2 }, uFrom: { value: 2 }, uSweep: { value: 1 }, uStart: { value: SWEEP_START },
      uScale: { value: scale }, uHover: { value: -1 }, uDim: { value: 0.06 },
    },
  });
}

/* ------------------------------------------------------------------------------------------- sweep clock */
function useSweep(mats: THREE.ShaderMaterial[], position: number, fromPosition: number, sweepId: number, onAngle: (a: number | null) => void) {
  const start = useRef<number | null>(null);
  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
  useEffect(() => {
    for (const m of mats) { m.uniforms.uCp.value = position; m.uniforms.uFrom.value = fromPosition; m.uniforms.uSweep.value = reduced ? 1 : 0; }
    start.current = reduced || position === fromPosition ? null : performance.now();
  }, [sweepId]); // eslint-disable-line react-hooks/exhaustive-deps
  useFrame(() => {
    if (start.current == null) { onAngle(null); return; }
    const t = Math.min(1, (performance.now() - start.current) / 2200);
    const e = 1 - Math.pow(1 - t, 3);
    for (const m of mats) m.uniforms.uSweep.value = e;
    onAngle(t < 1 ? SWEEP_START + e * TAU : null);
    if (t >= 1) { start.current = null; for (const m of mats) m.uniforms.uFrom.value = m.uniforms.uCp.value; }
  });
}

/* ------------------------------------------------------------------------------------------- comments */
interface SceneProps {
  points: PointsPayload;
  sources: SourcesPayload | undefined;
  mask: Uint8Array;            // 1 = matches the current key filter
  position: number; fromPosition: number; sweepId: number;
  hover: number | null;
  onHover: (i: number | null, x: number, y: number) => void;
  onPick: (i: number) => void;
}

export function Scene(p: SceneProps) {
  const { gl } = useThree();
  const dpr = gl.getPixelRatio();
  const commentMat = useMemo(() => contactMaterial(15 * dpr), [dpr]);
  const researchMat = useMemo(() => contactMaterial(20 * dpr), [dpr]);
  const sweepRef = useRef<THREE.Group>(null);

  const geom = useMemo(() => {
    const c = p.points.cols, n = p.points.n;
    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      pos[i * 3] = c.x[i]; pos[i * 3 + 1] = c.y[i] * 0.72; pos[i * 3 + 2] = c.z[i];
      cp[i] = c.cp[i]; az[i] = Math.atan2(c.z[i], c.x[i]); idx[i] = i;
      size[i] = 0.85 + Math.min(0.8, Math.sqrt(c.len[i] / 300));
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    g.setAttribute("aCp", new THREE.BufferAttribute(cp, 1));
    g.setAttribute("aAz", new THREE.BufferAttribute(az, 1));
    g.setAttribute("aSize", new THREE.BufferAttribute(size, 1));
    g.setAttribute("aIdx", new THREE.BufferAttribute(idx, 1));
    g.setAttribute("aSel", new THREE.BufferAttribute(new Float32Array(n).fill(1), 1));
    g.computeBoundingSphere();
    return g;
  }, [p.points]);

  useEffect(() => {
    const a = geom.getAttribute("aSel") as THREE.BufferAttribute;
    for (let i = 0; i < p.mask.length; i++) a.setX(i, p.mask[i]);
    a.needsUpdate = true;
  }, [geom, p.mask]);
  useEffect(() => { commentMat.uniforms.uHover.value = p.hover ?? -1; }, [commentMat, p.hover]);

  const research = useMemo(() => {
    const items = p.sources?.research ?? [];
    const n = items.length;
    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
    items.forEach((it, i) => {
      const a = timeAngle(it.published_at);
      const lane = (it.id % 7) / 7;                         // spread same-day items across the ring's width
      const [x, , z] = polar(R.time + (lane - 0.5) * 0.12, a);
      pos.set([x, (lane - 0.5) * 0.05, z], i * 3);
      cp[i] = it.new ? 2 : 1; az[i] = a; size[i] = it.tier === "T1" ? 1.5 : 1.1; idx[i] = -10;
    });
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    g.setAttribute("aCp", new THREE.BufferAttribute(cp, 1));
    g.setAttribute("aAz", new THREE.BufferAttribute(az, 1));
    g.setAttribute("aSize", new THREE.BufferAttribute(size, 1));
    g.setAttribute("aIdx", new THREE.BufferAttribute(idx, 1));
    g.setAttribute("aSel", new THREE.BufferAttribute(new Float32Array(n).fill(1), 1));
    return g;
  }, [p.sources]);

  useSweep([commentMat, researchMat], p.position, p.fromPosition, p.sweepId, (a) => {
    const g = sweepRef.current;
    if (!g) return;
    g.visible = a != null;
    if (a != null) g.rotation.y = -a;
  });

  const visibleAt = (i: number) => p.mask[i] === 1 && p.points.cols.cp[i] <= p.position;
  const move = (e: ThreeEvent<PointerEvent>) => {
    const hit = e.intersections.find((h) => h.object === e.object && h.index != null && visibleAt(h.index));
    if (hit?.index != null) { e.stopPropagation(); p.onHover(hit.index, e.nativeEvent.clientX, e.nativeEvent.clientY); }
    else p.onHover(null, 0, 0);
  };
  const click = (e: ThreeEvent<MouseEvent>) => {
    const hit = e.intersections.find((h) => h.object === e.object && h.index != null && visibleAt(h.index));
    if (hit?.index != null) { e.stopPropagation(); p.onPick(hit.index); }
  };

  return (
    <>
      <OrbitControls makeDefault enablePan={false} minDistance={2.2} maxDistance={9} autoRotate autoRotateSpeed={0.25}
                     enableDamping dampingFactor={0.08} maxPolarAngle={Math.PI * 0.62} />
      <points geometry={geom} material={commentMat} onPointerMove={move} onPointerOut={() => p.onHover(null, 0, 0)} onClick={click} />
      <points geometry={research} material={researchMat} />
      <Rings sources={p.sources} />
      <group ref={sweepRef} visible={false}><SweepBlade /></group>
    </>
  );
}

/* ------------------------------------------------------------------------------------------- the sweep */
function SweepBlade() {
  const mat = useMemo(() => new THREE.ShaderMaterial({
    transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending,
    vertexShader: "varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }",
    fragmentShader: "varying vec2 vUv; void main(){ float a = (1.0 - vUv.x * 0.7) * (1.0 - abs(vUv.y - 0.5) * 2.0); gl_FragColor = vec4(0.18, 0.45, 0.95, 0.32 * a); }",
  }), []);
  return (
    <>
      <mesh material={mat} position={[R.time / 2 + 0.1, 0, 0]}><planeGeometry args={[R.time + 0.2, 1.4]} /></mesh>
      <mesh position={[(R.time + 0.2) / 2, 0, 0]}><boxGeometry args={[R.time + 0.2, 0.004, 0.004]} /><meshBasicMaterial color="#4d94ff" /></mesh>
    </>
  );
}

/* ------------------------------------------------------------------------------------------- source rings */
function ringPoints(r: number, a0 = 0, a1 = TAU, seg = 256) {
  const pts: THREE.Vector3[] = [];
  for (let i = 0; i <= seg; i++) { const a = a0 + ((a1 - a0) * i) / seg; pts.push(new THREE.Vector3(...polar(r, a))); }
  return new THREE.BufferGeometry().setFromPoints(pts);
}

function Rings({ sources }: { sources: SourcesPayload | undefined }) {
  const lines = useMemo(() => {
    const guide = new THREE.LineBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.1 });
    const out: THREE.Line[] = [R.study, R.options, R.sales].flatMap((r) => CARS.map((car) => new THREE.Line(ringPoints(r, ...sector(car), 64), guide)));
    const time = new THREE.Line(ringPoints(R.time, TIME_START - 0.12, TIME_START + (300 / 360) * TAU, 360),
      new THREE.LineDashedMaterial({ color: "#ffffff", transparent: true, opacity: 0.22, dashSize: 0.02, gapSize: 0.025 }));
    time.computeLineDistances();
    out.push(time);
    return out;
  }, []);

  // study: one radial tick per item, outward = above its own column's average, inward = below (z-score)
  const study = useMemo(() => {
    const list = sources?.study ?? [];
    const v: number[] = [];
    const groups = new Map<string, typeof list>();
    for (const s of list) { const k = s.car; groups.set(k, [...(groups.get(k) ?? []), s]); }
    for (const [car, items] of groups) {
      const [a0, a1] = sector(car);
      items.forEach((s, i) => {
        const a = a0 + ((a1 - a0) * (i + 0.5)) / items.length;
        const z = Math.max(-2.5, Math.min(2.5, s.z ?? 0)) * 0.05;
        v.push(...polar(R.study, a), ...polar(R.study + z, a));
      });
    }
    return new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3));
  }, [sources]);

  // options: one dot per equipment option of today's car
  const options = useMemo(() => {
    const v: number[] = [];
    for (const o of sources?.options ?? []) {
      const [a0, a1] = sector(o.car);
      for (let i = 0; i < o.n; i++) v.push(...polar(R.options + ((i % 3) - 1) * 0.018, a0 + ((a1 - a0) * (i + 0.5)) / o.n));
    }
    return new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3));
  }, [sources]);

  // sales: one bar per car × market × year; 2030 forecast drawn as an outline
  const bars = useMemo(() => {
    const rows = (sources?.sales ?? []).filter((s) => s.units && s.units > 0);
    const byCar = new Map<string, typeof rows>();
    for (const s of rows) byCar.set(s.car, [...(byCar.get(s.car) ?? []), s]);
    const out: { pos: [number, number, number]; rot: number; h: number; forecast: boolean }[] = [];
    for (const [car, items] of byCar) {
      const [a0, a1] = sector(car);
      items.forEach((s, i) => {
        const a = a0 + ((a1 - a0) * (i + 0.5)) / items.length;
        const h = Math.max(0.01, (s.units! / 120000) * 0.3);
        out.push({ pos: polar(R.sales, a, h / 2), rot: -a, h, forecast: !!s.is_forecast });
      });
    }
    return out;
  }, [sources]);

  return (
    <group>
      {lines.map((l, i) => <primitive key={i} object={l} />)}
      <lineSegments geometry={study}><lineBasicMaterial color="#dfe4ea" transparent opacity={0.55} /></lineSegments>
      <points geometry={options}><pointsMaterial color="#dfe4ea" size={0.012} transparent opacity={0.55} /></points>
      {bars.map((b, i) => (
        <mesh key={i} position={b.pos} rotation={[0, b.rot, 0]}>
          <boxGeometry args={[0.008, b.h, 0.008]} />
          {b.forecast ? <meshBasicMaterial color="#4d94ff" wireframe transparent opacity={0.4} /> : <meshBasicMaterial color="#dfe4ea" transparent opacity={0.45} />}
        </mesh>
      ))}
      {CARS.map((car) => {
        const [a0, a1] = sector(car);
        return (
          <Html key={car} position={polar(R.labels, (a0 + a1) / 2)} center zIndexRange={[10, 0]}>
            <div className="ring-label"><b>{CAR_NAME[car]}</b><span>{car}</span></div>
          </Html>
        );
      })}
      {[["JUL 25", "2025-07-01"], ["JAN 26", "2026-01-31"], ["JUL 26", "2026-07-31"]].map(([t, d]) => (
        <Html key={t} position={polar(R.time + 0.16, timeAngle(d), 0)} center zIndexRange={[10, 0]}>
          <div className="time-label">{t}</div>
        </Html>
      ))}
    </group>
  );
}

