      </div>
      <div className="sweepctl-tracks" aria-live="polite">
        <span className="label sweepctl-cap">all sources</span>
        {cp === "cp2" && late?.acquire ? (
          <>
            <span><i className="mark held" aria-hidden />{fmt(late.acquire.tracks.held)}<span className="label">held</span></span>
            <span><i className="mark new" aria-hidden />{fmt(late.acquire.tracks.new)}<span className="label">new</span></span>
          </>
        ) : (
          <span><i className="mark new" aria-hidden />{fmt(byId.cp1?.acquire?.tracks.new)}<span className="label">acquired</span></span>
        )}
      </div>
    </div>
  );
}
