// The checkpoint is app-wide state: every screen reads what is visible at the current checkpoint, and every screen
// can animate the change from the previous one (the sweep). The URL (?cp=) is the source of truth so a view can be
// linked; ← / → step between checkpoints anywhere in the app.
import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { useQuery } from "@tanstack/react-query";
import { useSearchParams } from "react-router-dom";
import { api } from "@/lib/api";
import type { Checkpoint, CheckpointId } from "@/lib/types";

const ORDER: CheckpointId[] = ["cp1", "cp2"];
const isCp = (v: string | null): v is CheckpointId => v === "cp1" || v === "cp2";

interface Ctx {
  cp: CheckpointId;
  from: CheckpointId;        // checkpoint before the latest switch (equals cp when settled)
  sweepId: number;           // increments on every switch; screens restart their sweep on change
  setCp: (cp: CheckpointId) => void;
  checkpoints: Checkpoint[] | undefined;
  current: Checkpoint | undefined;
  position: number;          // 1 | 2
}

const CheckpointCtx = createContext<Ctx | null>(null);

export function CheckpointProvider({ children }: { children: ReactNode }) {
  const [params, setParams] = useSearchParams();
  const urlCp = params.get("cp");
  const cp: CheckpointId = isCp(urlCp) ? urlCp : "cp2";
  const prev = useRef<CheckpointId>(cp);
  const [from, setFrom] = useState<CheckpointId>(cp);
  const [sweepId, setSweepId] = useState(0);
  const { data: checkpoints } = useQuery({ queryKey: ["checkpoints"], queryFn: () => api.get<Checkpoint[]>("/api/checkpoints") });

  useEffect(() => {
    if (prev.current !== cp) {
      setFrom(prev.current);
      setSweepId((n) => n + 1);
      prev.current = cp;
    }
  }, [cp]);

  const setCp = useCallback(
    (next: CheckpointId) => {
      setParams((p) => { const q = new URLSearchParams(p); q.set("cp", next); return q; }, { replace: true });
    },
    [setParams],
  );

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLElement && e.target.closest("input, textarea, [contenteditable]")) return;
      const i = ORDER.indexOf(cp);
      if (e.key === "ArrowRight" && i < ORDER.length - 1) setCp(ORDER[i + 1]);
      if (e.key === "ArrowLeft" && i > 0) setCp(ORDER[i - 1]);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [cp, setCp]);

  const value = useMemo<Ctx>(() => {
    const current = checkpoints?.find((c) => c.id === cp);
    return { cp, from, sweepId, setCp, checkpoints, current, position: ORDER.indexOf(cp) + 1 };
  }, [cp, from, sweepId, setCp, checkpoints]);

  return <CheckpointCtx.Provider value={value}>{children}</CheckpointCtx.Provider>;
}

export function useCheckpoint(): Ctx {
  const c = useContext(CheckpointCtx);
  if (!c) throw new Error("useCheckpoint outside CheckpointProvider");
  return c;
}

export const CHECKPOINT_ORDER = ORDER;
// Geometry of the scan volume. The comment galaxy sits in the unit ball; range rings around it carry the other raw
// sources. Angles on the car rings are sectors (one per car line); the outer ring is a time ring where the angle is
// the publication date, so the sweep that reveals the second checkpoint passes the newer research in date order.

export const TAU = Math.PI * 2;

export const CARS = ["F70", "G60", "G68", "G70"] as const;
export const CAR_NAME: Record<string, string> = { F70: "1 Series", G60: "5 Series", G68: "5 Series LWB", G70: "7 Series" };
export const MARKET_NAME: Record<string, string> = { EU: "Europe", US: "USA", CN: "China", RoW: "Rest of world" };

export const R = { study: 1.42, options: 1.62, sales: 1.86, time: 2.18, labels: 2.5 } as const;

const GAP = 0.06; // radians between car sectors
export function sector(car: string): [number, number] {
  const i = Math.max(0, CARS.indexOf(car as (typeof CARS)[number]));
  const a0 = (i * TAU) / CARS.length + GAP / 2;
  return [a0, a0 + TAU / CARS.length - GAP];
}

// Time ring: Jul 2025 → Jul 2026 over 300°, starting a quarter turn back from the Jan cut-off so Jan sits at the
// viewer's right. Older items collect just before the start.
const T0 = Date.parse("2025-07-01");
const T1 = Date.parse("2026-07-31");
const SPAN = (300 / 360) * TAU;
export const TIME_START = -SPAN * ((Date.parse("2026-01-31") - T0) / (T1 - T0));
export function timeAngle(iso: string | null): number {
  const t = iso ? Date.parse(iso.length === 7 ? `${iso}-28` : iso.length === 4 ? `${iso}-12-31` : iso) : NaN;
  if (Number.isNaN(t) || t < T0) return TIME_START - 0.08;
  return TIME_START + SPAN * Math.min(1, (t - T0) / (T1 - T0));
}
export const SWEEP_START = timeAngle("2026-01-31"); // the sweep to JUL starts at the JAN cut-off

export const polar = (r: number, a: number, y = 0): [number, number, number] => [r * Math.cos(a), y, r * Math.sin(a)];
// Successor: one scan volume per checkpoint. Screens are added as the pipeline stages are rebuilt
// (classify → cluster → contextualize → elicit); each reads the shared checkpoint from useCheckpoint().
import { Navigate, Route, Routes } from "react-router-dom";
import { CheckpointProvider } from "@/state/checkpoint";
import { SweepControl } from "@/components/SweepControl";
import { Scan } from "@/screens/scan/Scan";

export default function App() {
  return (
    <CheckpointProvider>
      <Routes>
        <Route path="/" element={<Scan />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
      <SweepControl />
    </CheckpointProvider>
  );
}
