          <button
            key={id}
            role="radio"
            aria-checked={cp === id}
            className="sweepctl-node"
            data-on={cp === id || (cp === "cp2" && id === "cp1") ? "" : undefined}
            onClick={() => setCp(id)}
          >
            <span className="sweepctl-dot" aria-hidden />
            <span className="sweepctl-name">{byId[id]?.label ?? (id === "cp1" ? "JAN 26" : "JUL 26")}</span>
